import{_ as i}from"./chunks/nosys.BGZSiay8.js";import{_ as l,c as t,a4 as o,o as r}from"./chunks/framework.BDeXF6e8.js";const f=JSON.parse('{"title":"Fetch ai","description":"","frontmatter":{},"headers":[],"relativePath":"network/index.md","filePath":"network/index.md","lastUpdated":1748920997000}'),a={name:"network/index.md"};function s(n,e,c,h,d,p){return r(),t("div",null,e[0]||(e[0]=[o('<h1 id="fetch-ai" tabindex="-1">Fetch ai <a class="header-anchor" href="#fetch-ai" aria-label="Permalink to &quot;Fetch ai&quot;">​</a></h1><pre><code>使用 `fetch` 函数即可立即向服务器发送网络请求\n</code></pre><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>该函数有两个参数：</p><ol><li>必填，字符串，请求地址</li><li>选填，对象，请求配置</li></ol><p><strong>请求配置对象</strong></p><ul><li>method：字符串，请求方法，默认值 GET</li><li>headers：对象，请求头信息</li><li>body: 请求体的内容，必须匹配请求头中的 Content-Type</li><li>mode：字符串，请求模式 <ul><li>cors：默认值，配置为该值，会在请求头中加入 origin 和 referer</li><li>no-cors：配置为该值，不会在请求头中加入 origin 和 referer，跨域的时候可能会出现问题</li><li>same-origin：指示请求必须在同一个域中发生，如果请求其他域，则会报错</li></ul></li><li>credentials: 如何携带凭据（cookie） <ul><li>omit：默认值，不携带 cookie</li><li>same-origin：请求同源地址时携带 cookie</li><li>include：请求任何地址都携带 cookie</li></ul></li><li>cache：配置缓存模式 <ul><li>default: 表示 fetch 请求之前将检查下 http 的缓存.</li><li>no-store: 表示 fetch 请求将完全忽略 http 缓存的存在. 这意味着请求之前将不再检查下 http 的缓存, 拿到响应后, 它也不会更新 http 缓存.</li><li>no-cache: 如果存在缓存, 那么 fetch 将发送一个条件查询 request 和一个正常的 request, 拿到响应后, 它会更新 http 缓存.</li><li>reload: 表示 fetch 请求之前将忽略 http 缓存的存在, 但是请求拿到响应后, 它将主动更新 http 缓存.</li><li>force-cache: 表示 fetch 请求不顾一切的依赖缓存, 即使缓存过期了, 它依然从缓存中读取. 除非没有任何缓存, 那么它将发送一个正常的 request.</li><li>only-if-cached: 表示 fetch 请求不顾一切的依赖缓存, 即使缓存过期了, 它依然从缓存中读取. 如果没有缓存, 它将抛出网络错误(该设置只在 mode 为”same-origin”时有效).</li></ul></li></ul><h2 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h2><p>fetch 函数返回一个 Promise 对象</p><ul><li>当收到服务器的返回结果后，Promise 进入 resolved 状态，状态数据为 Response 对象</li><li>当网络发生错误（或其他导致无法完成交互的错误）时，Promise 进入 rejected 状态，状态数据为错误信息</li></ul><p><strong>Response 对象</strong></p><ul><li>ok：boolean，当响应消息码在 200~299 之间时为 true，其他为 false</li><li>status：number，响应的状态码</li><li>text()：用于处理文本格式的 Ajax 响应。它从响应中获取文本流，将其读完，然后返回一个被解决为 string 对象的 Promise。</li><li>blob()：用于处理二进制文件格式（比如图片或者电子表格）的 Ajax 响应。它读取文件的原始数据，一旦读取完整个文件，就返回一个被解决为 blob 对象的 Promise。</li><li>json()：用于处理 JSON 格式的 Ajax 的响应。它将 JSON 数据流转换为一个被解决为 JavaScript 对象的 promise。</li><li>redirect()：可以用于重定向到另一个 URL。它会创建一个新的 Promise，以解决来自重定向的 URL 的响应。 <img src="'+i+'" alt="暂无更换"></li></ul>',12)]))}const x=l(a,[["render",s]]);export{f as __pageData,x as default};
